using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(Name = "config://app-settings",
    Description = "Returns the current application configuration")]
public class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["version"] = "1.0.0",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["limits"] = new Dictionary<string, int>
        {
            ["maxRequestsPerMinute"] = 100,
            ["maxUploadSizeMb"] = 50
        }
    };

    [ResourceFunction]
    public static string GetConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet(
        [Description("The name of the person to greet")] string name,
        [Description("Optional greeting style: formal or casual")] string style = "casual")
    {
        return style == "formal"
            ? $"Good day, {name}. How may I assist you?"
            : $"Hey {name}! What's up?";
    }
}

